//! Independent reference values for the boxplot, tolerance interval and
//! polynomial curve fit.
//!
//! `tests/reference/charts2.json` is generated by `tools/gen_charts2.py`; the
//! test never runs Python. The boxplot oracle interpolates the quartiles at
//! `h = (n + 1)p`, the captured convention, so it agrees with the engine
//! instead of using numpy's default position.

use fp_core::boxplot;
use fp_core::curvefit::{self, CurveModel};
use fp_core::data::{Column, DataFrame};
use fp_core::tolerance;
use serde_json::Value;

fn reference() -> Value {
    let raw = include_str!("reference/charts2.json");
    serde_json::from_str(raw).expect("valid JSON reference")
}

fn numbers(value: &Value) -> Vec<f64> {
    value
        .as_array()
        .expect("number list")
        .iter()
        .map(|value| value.as_f64().expect("number"))
        .collect()
}

fn close(actual: f64, expected: f64, tolerance: f64, what: &str) {
    assert!(
        (actual - expected).abs() <= tolerance * (1.0 + expected.abs()),
        "{what}: {actual} vs oracle {expected}"
    );
}

#[test]
fn the_boxplot_matches_the_r7_rules() {
    let r = reference();
    let tolerance = r["tolerance"].as_f64().expect("tolerance");
    let case = &r["boxplot"];
    let mut values = Vec::new();
    let mut labels = Vec::new();
    for (label, group) in case["groups"].as_object().expect("groups") {
        for value in group.as_array().expect("group") {
            values.push(value.as_f64().expect("value"));
            labels.push(label.clone());
        }
    }
    let df = DataFrame::new(vec![
        Column::new_f64("value", values),
        Column::new_text("group", labels),
    ])
    .expect("frame");
    let model = boxplot::fit(&df, "value", Some("group")).expect("boxplot");
    assert_eq!(model.groups.len(), 2);
    for group in &model.groups {
        let expected = &case["boxes"][&group.label];
        assert_eq!(group.n, expected["n"].as_u64().expect("n") as usize);
        for (actual, key) in [
            (group.min, "min"),
            (group.q1, "q1"),
            (group.median, "median"),
            (group.q3, "q3"),
            (group.max, "max"),
            (group.lower_whisker, "lower_whisker"),
            (group.upper_whisker, "upper_whisker"),
        ] {
            close(
                actual,
                expected[key].as_f64().expect("value"),
                tolerance,
                key,
            );
        }
        let outliers = numbers(&expected["outliers"]);
        assert_eq!(group.outliers.len(), outliers.len());
        for (actual, expected) in group.outliers.iter().zip(outliers) {
            close(*actual, expected, tolerance, "outlier");
        }
    }
}

#[test]
fn the_tolerance_factor_and_interval_match_howe() {
    let r = reference();
    let case = &r["tolerance_interval"];
    let tolerance = r["tolerance"].as_f64().expect("tolerance");
    let n = numbers(&case["values"]).len();
    let proportion = case["proportion"].as_f64().expect("proportion");
    let confidence = case["confidence"].as_f64().expect("confidence");
    close(
        tolerance::factor(n, proportion, confidence).expect("factor"),
        case["factor"].as_f64().expect("factor"),
        tolerance,
        "factor",
    );
    let interval = tolerance::interval(
        case["mean"].as_f64().expect("mean"),
        case["sd"].as_f64().expect("sd"),
        n,
        proportion,
        confidence,
    )
    .expect("interval");
    let expected = numbers(&case["interval"]);
    close(interval.0, expected[0], tolerance, "lower");
    close(interval.1, expected[1], tolerance, "upper");
}

#[test]
fn the_polynomial_curve_fit_matches_numpy() {
    let r = reference();
    let case = &r["curve_fit"];
    let tolerance = r["tolerance"].as_f64().expect("tolerance");
    let df = DataFrame::new(vec![
        Column::new_f64("x", numbers(&case["x"])),
        Column::new_f64("y", numbers(&case["y"])),
    ])
    .expect("frame");
    let model = curvefit::fit(&df, "x", "y", CurveModel::Polynomial(2), 0.95).expect("curve fit");
    assert_eq!(model.n, 10);
    let coefficients = numbers(&case["coefficients"]);
    assert_eq!(model.coefficients.len(), coefficients.len());
    for (actual, expected) in model.coefficients.iter().zip(coefficients) {
        close(*actual, expected, tolerance, "coefficient");
    }
    close(
        model.r_squared,
        case["r_squared"].as_f64().expect("R²"),
        tolerance,
        "R²",
    );
    close(
        model.residual_standard_error,
        case["residual_standard_error"].as_f64().expect("S"),
        tolerance,
        "S",
    );
}

#[test]
fn invalid_inputs_are_rejected() {
    let r = reference();
    let case = &r["curve_fit"];
    let df = DataFrame::new(vec![
        Column::new_f64("x", numbers(&case["x"])),
        Column::new_f64("y", numbers(&case["y"])),
    ])
    .expect("frame");
    assert!(curvefit::fit(&df, "x", "y", CurveModel::Polynomial(0), 0.95).is_err());
    assert!(tolerance::factor(1, 0.95, 0.95).is_err());
    assert!(tolerance::factor(20, 1.5, 0.95).is_err());
    assert!(boxplot::fit(&df, "missing", None).is_err());
}
